begin;
-- Preserve function OIDs and ACLs, serialize every actor with canonical account
-- changes, then recheck authorization after every resource/table-lock wait.

create function private.dsr_erasure_lock_actors_v1(p_actors uuid[])returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$begin
 -- Same global serialization key as the canonical account-governance commands.
 perform pg_advisory_xact_lock(hashtextextended('platform.account.access',0));
 perform 1 from auth.users where id=any(p_actors)order by id for share;
 perform 1 from public.platform_user_roles where user_id=any(p_actors)order by user_id,role_code for share;
 -- Native GoTrue session deletion must serialize with this caller too.
 if coalesce(auth.jwt()->>'session_id','')~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'then perform 1 from auth.sessions where id=(auth.jwt()->>'session_id')::uuid and user_id=auth.uid()for share;end if;
end$$;

create function private.dsr_erasure_assert_current_actor_v1(p_legal boolean default true)returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$begin
 if auth.uid()is null then raise exception'DSR_CURRENT_ACTOR_REQUIRED'using errcode='42501';end if;
 perform private.dsr_erasure_lock_actors_v1(array[auth.uid()]);
 if not private.current_auth_session_active_v1()or auth.jwt()->>'aal'is distinct from'aal2'then if p_legal then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';else raise exception'DSR_VERIFIED_ERASURE_SUBJECT_REQUIRED'using errcode='42501';end if;end if;if p_legal and not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
end$$;

create or replace function private.dsr_erasure_validate_rule_v1(p_source jsonb,p_rule jsonb)returns void language plpgsql immutable set search_path=pg_catalog as $$begin
 if jsonb_typeof(p_rule)is distinct from'object'or p_rule->>'schema_version'is distinct from'2'or(p_rule-array['schema_version','action','minimum_age_days','not_before','retention_until','authorization_valid_until','retained_fields_until','legal_reference','reason'])<>'{}'::jsonb or coalesce(p_rule->>'action','')not in('RETAIN_LEGAL','ACTION_REQUIRED','ANONYMIZE_DISPLAY_NAME','ERASE_REMOVED_FAVORITE_NOTES','ERASE_PHYSICAL_STORAGE')or jsonb_typeof(p_rule->'minimum_age_days')is distinct from'number'or coalesce(p_rule->>'minimum_age_days','')!~'^[0-9]{1,6}$'or(p_rule->>'minimum_age_days')::integer>365000 or length(btrim(coalesce(p_rule->>'legal_reference','')))not between 8 and 1000 or length(btrim(coalesce(p_rule->>'reason','')))not between 10 and 2000 or p_rule->>'not_before'is null or p_rule->>'authorization_valid_until'is null or not(p_rule?'retention_until')or not(p_rule?'retained_fields_until')then raise exception'DSR_ERASURE_EXPLICIT_POLICY_V2_REQUIRED'using errcode='22023';end if;
 perform(p_rule->>'not_before')::timestamptz;perform(p_rule->>'authorization_valid_until')::timestamptz;perform(p_rule->>'retention_until')::timestamptz;perform(p_rule->>'retained_fields_until')::timestamptz;
 if(p_rule->>'authorization_valid_until')::timestamptz<=(p_rule->>'not_before')::timestamptz or(p_rule->>'action'<>'ACTION_REQUIRED'and p_rule->>'retention_until'is null)or(p_rule->>'action'not in('RETAIN_LEGAL','ACTION_REQUIRED')and(p_rule->>'authorization_valid_until')::timestamptz<=(p_rule->>'retention_until')::timestamptz)then raise exception'DSR_ERASURE_INVALID_POLICY_DATES'using errcode='22023';end if;
 if p_rule->>'action'not in('RETAIN_LEGAL','ACTION_REQUIRED')and p_rule->>'action'is distinct from p_source->>'native_action'then raise exception'DSR_ERASURE_COMMAND_NOT_ALLOWLISTED'using errcode='22023';end if;
 if(p_rule->>'action'not in('ERASE_PHYSICAL_STORAGE','ACTION_REQUIRED')and p_rule->>'retained_fields_until'is null)or(p_rule->>'retained_fields_until'is not null and(p_rule->>'retained_fields_until')::timestamptz<(p_rule->>'retention_until')::timestamptz)or(p_rule->>'action'='ERASE_PHYSICAL_STORAGE'and p_rule->>'retained_fields_until'is not null)then raise exception'DSR_ERASURE_EXPLICIT_RETAINED_FIELDS_POLICY_REQUIRED'using errcode='22023';end if;
end$$;
create or replace function public.confirm_my_dsr_erasure_scope_v1(p_request_id uuid,p_scope_confirmed boolean,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare d public.data_subject_requests%rowtype;s public.dsr_erasure_scopes_v1%rowtype;h text;begin
 perform private.dsr_erasure_assert_current_actor_v1(false);select*into d from public.data_subject_requests where id=p_request_id for update;
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or d.id is null or d.request_type<>'ERASURE'or d.verified_at is null or d.status<>'IN_REVIEW'or private.dsr_account_subject_v1(d.id)is distinct from auth.uid()then raise exception'DSR_VERIFIED_ERASURE_SUBJECT_REQUIRED'using errcode='42501';end if;
 if p_scope_confirmed is distinct from true or length(btrim(coalesce(p_idempotency_key,'')))not between 8 and 200 then raise exception'DSR_ERASURE_SCOPE_CONFIRMATION_REQUIRED'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('request',d.id,'subject',auth.uid(),'organization',d.organization_id,'scope','ACCOUNT_AND_DSR_ORGANIZATION'));
 select*into s from public.dsr_erasure_scopes_v1 where request_id=d.id and idempotency_key=p_idempotency_key;if s.id is not null then return jsonb_build_object('outcome','DSR_ERASURE_SCOPE_CONFIRMED','scope_version_id',s.id,'scope_hash',s.content_hash);end if;
 insert into public.dsr_erasure_scopes_v1(request_id,subject_user_id,organization_id,version,scope_code,content_hash,idempotency_key)select d.id,auth.uid(),d.organization_id,coalesce(max(version),0)+1,'ACCOUNT_AND_DSR_ORGANIZATION',h,p_idempotency_key from public.dsr_erasure_scopes_v1 where request_id=d.id returning*into s;
 perform private.dsr_erasure_emit_v1(d.id,s.id,'privacy.erasure.scope.confirmed','DsrErasureScopeConfirmedV1',jsonb_build_object('request_id',d.id,'scope_version_id',s.id,'scope_hash',h));return jsonb_build_object('outcome','DSR_ERASURE_SCOPE_CONFIRMED','scope_version_id',s.id,'scope_hash',h);
end$$;

create or replace function public.create_dsr_erasure_draft_v1(p_request_id uuid,p_scope_version_id uuid,p_reason text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare draft public.dsr_erasure_drafts_v1%rowtype;cat jsonb;env text;begin
 perform private.dsr_erasure_assert_current_actor_v1();perform 1 from public.data_subject_requests where id=p_request_id for update;perform private.dsr_erasure_scope_v1(p_request_id,p_scope_version_id);env:=private.dsr_erasure_environment_v1();
 if length(btrim(coalesce(p_reason,'')))not between 10 and 2000 or length(btrim(coalesce(p_idempotency_key,'')))not between 8 and 200 then raise exception'INVALID_DSR_ERASURE_DRAFT'using errcode='22023';end if;
 select*into draft from public.dsr_erasure_drafts_v1 where request_id=p_request_id and idempotency_key=p_idempotency_key;if draft.id is not null then if draft.scope_version_id<>p_scope_version_id or draft.reason<>btrim(p_reason)or draft.created_by<>auth.uid()then raise exception'IDEMPOTENCY_KEY_REUSED'using errcode='22023';end if;return jsonb_build_object('outcome','DSR_ERASURE_DRAFTED','draft_id',draft.id,'catalog_hash',draft.catalog_hash);end if;
 cat:=private.dsr_erasure_catalog_v1();insert into public.dsr_erasure_drafts_v1(request_id,scope_version_id,catalog_json,catalog_hash,environment,reason,created_by,idempotency_key)values(p_request_id,p_scope_version_id,cat,private.canonical_request_hash(cat),env,btrim(p_reason),auth.uid(),p_idempotency_key)returning*into draft;
 perform private.dsr_erasure_emit_v1(p_request_id,draft.id,'privacy.erasure.drafted','DsrErasureDraftedV1',jsonb_build_object('request_id',p_request_id,'draft_id',draft.id,'catalog_hash',draft.catalog_hash));return jsonb_build_object('outcome','DSR_ERASURE_DRAFTED','draft_id',draft.id,'catalog_hash',draft.catalog_hash);
end$$;

create or replace function public.configure_dsr_erasure_source_v1(p_draft_id uuid,p_source_key text,p_expected_row_version integer,p_config jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare draft public.dsr_erasure_drafts_v1%rowtype;source jsonb;r public.dsr_erasure_source_rules_v1%rowtype;begin
 perform private.dsr_erasure_assert_current_actor_v1();select*into draft from public.dsr_erasure_drafts_v1 where id=p_draft_id for update;perform private.dsr_erasure_assert_current_actor_v1();if draft.id is null or draft.created_by<>auth.uid()then raise exception'DSR_ERASURE_DRAFT_AUTHOR_REQUIRED'using errcode='42501';end if;perform private.dsr_erasure_scope_v1(draft.request_id,draft.scope_version_id);
 if exists(select 1 from public.dsr_erasure_plans_v1 where draft_id=draft.id)then raise exception'DSR_ERASURE_DRAFT_SEALED'using errcode='55000';end if;
 select value into source from jsonb_array_elements(draft.catalog_json)where value->>'key'=p_source_key;if source is null or p_expected_row_version is null or p_expected_row_version<0 then raise exception'INVALID_DSR_ERASURE_SOURCE'using errcode='22023';end if;perform private.dsr_erasure_validate_rule_v1(source,p_config);
 select*into r from public.dsr_erasure_source_rules_v1 where draft_id=draft.id and source_key=p_source_key;if coalesce(r.row_version,0)is distinct from p_expected_row_version then if r.config=p_config and r.row_version=p_expected_row_version+1 then return jsonb_build_object('outcome','DSR_ERASURE_SOURCE_CONFIGURED','row_version',r.row_version);end if;raise exception'STALE_DSR_ERASURE_SOURCE'using errcode='40001';end if;
 insert into public.dsr_erasure_source_rules_v1(draft_id,source_key,config,row_version)values(draft.id,p_source_key,p_config,1)on conflict(draft_id,source_key)do update set config=excluded.config,row_version=public.dsr_erasure_source_rules_v1.row_version+1,changed_at=clock_timestamp()returning*into r;
 perform private.dsr_erasure_emit_v1(draft.request_id,draft.id,'privacy.erasure.source.configured','DsrErasureSourceConfiguredV1',jsonb_build_object('draft_id',draft.id,'source_key',p_source_key,'row_version',r.row_version,'config_hash',private.canonical_request_hash(p_config)));return jsonb_build_object('outcome','DSR_ERASURE_SOURCE_CONFIGURED','row_version',r.row_version);
end$$;

create or replace function public.submit_dsr_erasure_plan_v1(p_draft_id uuid,p_expected_catalog_hash text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare draft public.dsr_erasure_drafts_v1%rowtype;s public.dsr_erasure_scopes_v1%rowtype;item jsonb;rule jsonb;entries jsonb:='[]';policy jsonb;plan public.dsr_erasure_plans_v1%rowtype;begin
 perform private.dsr_erasure_assert_current_actor_v1();select*into draft from public.dsr_erasure_drafts_v1 where id=p_draft_id for update;perform private.dsr_erasure_assert_current_actor_v1();
 if draft.id is null or draft.created_by<>auth.uid()then raise exception'DSR_ERASURE_DRAFT_AUTHOR_REQUIRED'using errcode='42501';end if;s:=private.dsr_erasure_scope_v1(draft.request_id,draft.scope_version_id);
 if p_expected_catalog_hash is distinct from draft.catalog_hash or draft.catalog_hash is distinct from private.canonical_request_hash(private.dsr_erasure_catalog_v1())or draft.environment is distinct from private.dsr_erasure_environment_v1()then raise exception'STALE_DSR_ERASURE_CATALOG_OR_ENVIRONMENT'using errcode='40001';end if;
 select*into plan from public.dsr_erasure_plans_v1 where draft_id=draft.id;if plan.id is not null then return jsonb_build_object('outcome','DSR_ERASURE_PLAN_SUBMITTED','plan_id',plan.id,'content_hash',plan.content_hash);end if;
 for item in select value from jsonb_array_elements(draft.catalog_json)loop
  select config into rule from public.dsr_erasure_source_rules_v1 where draft_id=draft.id and source_key=item->>'key';if rule is null then raise exception'DSR_ERASURE_UNCLASSIFIED_SOURCE'using errcode='55000';end if;perform private.dsr_erasure_validate_rule_v1(item,rule);
  if(rule->>'authorization_valid_until')::timestamptz<=clock_timestamp()or(rule->>'retained_fields_until')::timestamptz<=clock_timestamp()then raise exception'DSR_ERASURE_RETENTION_POLICY_EXPIRED'using errcode='55000';end if;
  entries:=entries||jsonb_build_array(jsonb_build_object('source_key',item->>'key','source',item,'config',rule,'target_hash',case when rule->>'action'in('ANONYMIZE_DISPLAY_NAME','ERASE_REMOVED_FAVORITE_NOTES')then private.dsr_erasure_target_hash_v1(draft.request_id,s.subject_user_id,item->>'key')else null end));
 end loop;
 policy:=jsonb_build_object('format','MATRICIA_ERASURE_PLAN_V1','request_id',draft.request_id,'scope_version_id',s.id,'scope_hash',s.content_hash,'organization_id',s.organization_id,'subject_user_id',s.subject_user_id,'environment',draft.environment,'catalog_hash',draft.catalog_hash,'sources',entries,'external_processing',private.dsr_all_external_processing_sources_v1(draft.request_id));
 insert into public.dsr_erasure_plans_v1(draft_id,request_id,scope_version_id,catalog_hash,environment,policy_json,content_hash,created_by)values(draft.id,draft.request_id,s.id,draft.catalog_hash,draft.environment,policy,private.canonical_request_hash(policy),auth.uid())returning*into plan;
 perform private.dsr_erasure_emit_v1(plan.request_id,plan.id,'privacy.erasure.plan.submitted','DsrErasurePlanSubmittedV1',jsonb_build_object('plan_id',plan.id,'content_hash',plan.content_hash));return jsonb_build_object('outcome','DSR_ERASURE_PLAN_SUBMITTED','plan_id',plan.id,'content_hash',plan.content_hash);
end$$;

create or replace function public.review_dsr_erasure_plan_v1(p_plan_id uuid,p_expected_content_hash text,p_approve boolean,p_policy_review_confirmed boolean,p_legal_reference text,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare p public.dsr_erasure_plans_v1%rowtype;r public.dsr_erasure_reviews_v1%rowtype;proof text;begin
 perform private.dsr_erasure_assert_current_actor_v1();select*into p from public.dsr_erasure_plans_v1 where id=p_plan_id for update;perform private.dsr_erasure_assert_current_actor_v1();
 if p.id is null or p.created_by=auth.uid()then raise exception'DSR_ERASURE_INDEPENDENT_REVIEW_REQUIRED'using errcode='42501';end if;perform private.dsr_erasure_scope_v1(p.request_id,p.scope_version_id);
 if p_expected_content_hash is distinct from p.content_hash or p.catalog_hash is distinct from private.canonical_request_hash(private.dsr_erasure_catalog_v1())or p.environment is distinct from private.dsr_erasure_environment_v1()then raise exception'STALE_DSR_ERASURE_PLAN'using errcode='40001';end if;
 if p_approve is null or(p_approve and p_policy_review_confirmed is distinct from true)or length(btrim(coalesce(p_legal_reference,'')))not between 8 and 1000 or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 then raise exception'DSR_ERASURE_DOCUMENTED_POLICY_REVIEW_REQUIRED'using errcode='22023';end if;
 proof:=private.canonical_request_hash(jsonb_build_object('plan_id',p.id,'content_hash',p.content_hash,'decision',p_approve,'reviewer',auth.uid(),'legal_reference',btrim(p_legal_reference),'reason',btrim(p_reason)));
 select*into r from public.dsr_erasure_reviews_v1 where plan_id=p.id;if r.plan_id is not null then if r.review_proof_hash<>proof then raise exception'DSR_ERASURE_ALREADY_REVIEWED'using errcode='55000';end if;else
 insert into public.dsr_erasure_reviews_v1(plan_id,content_hash,decision,legal_reference,reason,review_proof_hash,reviewed_by)values(p.id,p.content_hash,case when p_approve then'APPROVE'else'REJECT'end,btrim(p_legal_reference),btrim(p_reason),proof,auth.uid());
 perform private.dsr_erasure_emit_v1(p.request_id,p.id,'privacy.erasure.plan.reviewed','DsrErasurePlanReviewedV1',jsonb_build_object('plan_id',p.id,'content_hash',p.content_hash,'decision',case when p_approve then'APPROVE'else'REJECT'end,'review_proof_hash',proof));end if;
 return jsonb_build_object('outcome','DSR_ERASURE_PLAN_REVIEWED','plan_id',p.id,'decision',case when p_approve then'APPROVE'else'REJECT'end,'review_proof_hash',proof);
end$$;

create function private.dsr_erasure_policy_actor_active_v1(p_actor uuid)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select exists(select 1 from auth.users u where u.id=p_actor and u.deleted_at is null and(u.banned_until is null or u.banned_until<=clock_timestamp())and exists(select 1 from public.platform_user_roles r where r.user_id=u.id and r.revoked_at is null and r.role_code=any(array['SUPER_ADMIN','COMPLIANCE_MANAGER']::text[])))$$;
create function private.dsr_erasure_policy_context_core_v1(p_plan_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare p public.dsr_erasure_plans_v1%rowtype;r public.dsr_erasure_reviews_v1%rowtype;s public.dsr_erasure_scopes_v1%rowtype;physical jsonb;begin
 select*into p from public.dsr_erasure_plans_v1 where id=p_plan_id;select*into r from public.dsr_erasure_reviews_v1 where plan_id=p.id;
 perform pg_advisory_xact_lock(hashtextextended('platform.account.access',0));perform 1 from auth.users where id in(p.created_by,r.reviewed_by)order by id for share;perform 1 from public.platform_user_roles where user_id in(p.created_by,r.reviewed_by)order by user_id,role_code for share;
 perform 1 from public.data_subject_requests where id=p.request_id for update;select*into p from public.dsr_erasure_plans_v1 where id=p_plan_id for update;select*into r from public.dsr_erasure_reviews_v1 where plan_id=p.id;
 if exists(select 1 from public.dsr_erasure_revocations_v1 where plan_id=p.id)then raise exception'DSR_ERASURE_POLICY_REVOKED'using errcode='55000';end if;
 if p.id is null or r.decision is distinct from'APPROVE'or r.content_hash is distinct from p.content_hash or r.reviewed_by=p.created_by then raise exception'DSR_ERASURE_APPROVED_POLICY_REQUIRED'using errcode='55000';end if;
 -- Actor and session locks above also include a third-party executor.
 if not private.dsr_erasure_policy_actor_active_v1(p.created_by)or not private.dsr_erasure_policy_actor_active_v1(r.reviewed_by)or exists(select 1 from auth.users where id in(p.created_by,r.reviewed_by)and(deleted_at is not null or banned_until>clock_timestamp()))then raise exception'DSR_ERASURE_POLICY_AUTHORITY_REVOKED'using errcode='42501';end if;
 if p.catalog_hash is distinct from private.canonical_request_hash(private.dsr_erasure_catalog_v1())or p.environment is distinct from private.dsr_erasure_environment_v1()then raise exception'STALE_DSR_ERASURE_PLAN'using errcode='40001';end if;
 perform 1 from public.data_subject_requests where id=p.request_id for update;s:=private.dsr_erasure_scope_v1(p.request_id,p.scope_version_id);
 perform pg_advisory_xact_lock(hashtextextended('privacy-erasure:'||s.organization_id::text||':'||s.subject_user_id::text,0));lock table public.privacy_legal_holds in share mode;
 if exists(select 1 from public.privacy_legal_holds h join public.data_subject_requests d on d.id=p.request_id where h.organization_id=s.organization_id and h.subject_reference_hash=d.subject_reference_hash and h.status='ACTIVE'and h.starts_at<=clock_timestamp()and(h.ends_at is null or h.ends_at>clock_timestamp()))then raise exception'PRIVACY_LEGAL_HOLD_ACTIVE'using errcode='55000';end if;
 perform private.dsr_erasure_validate_rule_v1(x->'source',x->'config')from jsonb_array_elements(p.policy_json->'sources')x;
 if exists(select 1 from jsonb_array_elements(p.policy_json->'sources')x where(x#>>'{config,authorization_valid_until}')::timestamptz<=clock_timestamp()or(x#>>'{config,retained_fields_until}')::timestamptz<=clock_timestamp()or(x#>>'{config,not_before}')::timestamptz>clock_timestamp())then raise exception'DSR_ERASURE_POLICY_NOT_CURRENT'using errcode='55000';end if;
 if exists(select 1 from jsonb_array_elements(p.policy_json->'sources')x where x#>>'{config,action}'not in('RETAIN_LEGAL','ACTION_REQUIRED')and(x#>>'{config,retention_until}')::timestamptz>clock_timestamp())then raise exception'DSR_ERASURE_MINIMUM_RETENTION_NOT_REACHED'using errcode='55000';end if;
 select x->'config'into physical from jsonb_array_elements(p.policy_json->'sources')x where x->>'source_key'='@physical_storage';
 return jsonb_build_object('plan_id',p.id,'request_id',p.request_id,'subject_user_id',s.subject_user_id,'organization_id',s.organization_id,'content_hash',p.content_hash,'scope_version_id',s.id,'scope_hash',s.content_hash,'environment',p.environment,'physical_policy',physical,'review',jsonb_build_object('reviewer_id',r.reviewed_by,'review_proof_hash',r.review_proof_hash));
end$$;
create or replace function private.dsr_erasure_physical_context_v1(p_plan_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare result jsonb;begin
 if auth.role()is distinct from'service_role'then perform private.dsr_erasure_assert_current_actor_v1();end if;
 result:=private.dsr_erasure_policy_context_core_v1(p_plan_id);
 if auth.role()is distinct from'service_role'then perform private.dsr_erasure_assert_current_actor_v1();end if;
 return result;
end$$;

create or replace function public.execute_dsr_erasure_sources_v1(p_plan_id uuid,p_expected_content_hash text,p_expected_review_proof_hash text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare c jsonb;p public.dsr_erasure_plans_v1%rowtype;x jsonb;source_key_value text;action_value text;before_value text;after_value text;affected bigint;receipt public.dsr_erasure_source_receipts_v1%rowtype;retained text[];threshold timestamptz;proof text;begin
 perform private.dsr_erasure_assert_current_actor_v1();
 c:=private.dsr_erasure_physical_context_v1(p_plan_id);perform private.dsr_erasure_assert_current_actor_v1();select*into p from public.dsr_erasure_plans_v1 where id=p_plan_id for update;
 if p_expected_content_hash is distinct from p.content_hash or p_expected_review_proof_hash is distinct from c#>>'{review,review_proof_hash}'then raise exception'STALE_DSR_ERASURE_EXECUTION'using errcode='40001';end if;
 lock table public.organization_memberships,public.platform_user_roles in share mode;perform private.dsr_erasure_assert_current_actor_v1();
 perform 1 from public.user_profiles where id=(c->>'subject_user_id')::uuid for update;
 perform 1 from public.client_provider_favorites where client_organization_id=(c->>'organization_id')::uuid and created_by=(c->>'subject_user_id')::uuid order by id for update;
 -- The fixed allowlist is exhaustive here; no dynamic UPDATE/DELETE is accepted.
 for x in select value from jsonb_array_elements(p.policy_json->'sources')loop
  source_key_value:=x->>'source_key';action_value:=x#>>'{config,action}';if action_value not in('ANONYMIZE_DISPLAY_NAME','ERASE_REMOVED_FAVORITE_NOTES')then continue;end if;
  select*into receipt from public.dsr_erasure_source_receipts_v1 where plan_id=p.id and dsr_erasure_source_receipts_v1.source_key=source_key_value;if receipt.plan_id is not null then continue;end if;
  before_value:=private.dsr_erasure_target_hash_v1(p.request_id,(c->>'subject_user_id')::uuid,source_key_value);
  if before_value is distinct from x->>'target_hash'then raise exception'STALE_DSR_ERASURE_TARGET'using errcode='40001';end if;
  threshold:=clock_timestamp()-make_interval(days=>(x#>>'{config,minimum_age_days}')::integer);
  if action_value='ANONYMIZE_DISPLAY_NAME'then
   if exists(select 1 from public.organization_memberships where user_id=(c->>'subject_user_id')::uuid and(organization_id<>(c->>'organization_id')::uuid or status in('ACTIVE','INVITED')))or exists(select 1 from public.platform_user_roles where user_id=(c->>'subject_user_id')::uuid and revoked_at is null)or exists(select 1 from public.user_profiles where id=(c->>'subject_user_id')::uuid and updated_at>threshold)then raise exception'DSR_ERASURE_SHARED_OR_CURRENT_PROFILE_REQUIRED'using errcode='55000';end if;
   update public.user_profiles set display_name='Utilisateur anonymisé',updated_at=clock_timestamp(),row_version=row_version+1 where id=(c->>'subject_user_id')::uuid;get diagnostics affected=row_count;
   select array_agg(col->>'name'order by col->>'name')into retained from jsonb_array_elements(x#>'{source,columns}')col where col->>'name'<>'display_name';
  else
   if exists(select 1 from public.client_provider_favorites where client_organization_id=(c->>'organization_id')::uuid and created_by=(c->>'subject_user_id')::uuid and status='REMOVED'and removed_by=(c->>'subject_user_id')::uuid and removed_at>threshold)then raise exception'DSR_ERASURE_FAVORITE_RETENTION_NOT_DUE'using errcode='55000';end if;
   update public.client_provider_favorites set note=null,row_version=row_version+1 where client_organization_id=(c->>'organization_id')::uuid and created_by=(c->>'subject_user_id')::uuid and status='REMOVED'and removed_by=(c->>'subject_user_id')::uuid and note is not null;get diagnostics affected=row_count;
   select array_agg(col->>'name'order by col->>'name')into retained from jsonb_array_elements(x#>'{source,columns}')col where col->>'name'<>'note';
  end if;
  after_value:=private.dsr_erasure_target_hash_v1(p.request_id,(c->>'subject_user_id')::uuid,source_key_value);proof:=private.canonical_request_hash(jsonb_build_object('plan',p.id,'source',source_key_value,'action',action_value,'before',before_value,'after',after_value,'affected_rows',affected::text,'retained_fields',retained));
  insert into public.dsr_erasure_source_receipts_v1(plan_id,source_key,action,before_hash,after_hash,affected_rows,retained_fields,proof_hash)values(p.id,source_key_value,action_value,before_value,after_value,affected,coalesce(retained,'{}'),proof);
  perform private.dsr_erasure_emit_v1(p.request_id,p.id,'privacy.erasure.source.executed','DsrErasureSourceExecutedV1',jsonb_build_object('plan_id',p.id,'source_key',source_key_value,'action',action_value,'affected_rows',affected::text,'proof_hash',proof));
 end loop;
 return jsonb_build_object('outcome','DSR_ERASURE_NATIVE_SOURCES_EXECUTED','plan_id',p.id,'complete',false,'receipt_count',(select count(*)::text from public.dsr_erasure_source_receipts_v1 where plan_id=p.id),'physical_and_external_evidence_required',true);
end$$;

create or replace function public.prepare_dsr_erasure_report_v1(p_plan_id uuid,p_expected_content_hash text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare c jsonb;p public.dsr_erasure_plans_v1%rowtype;doc jsonb;sha text;e public.dsr_erasure_executions_v1%rowtype;begin
 perform private.dsr_erasure_assert_current_actor_v1();c:=private.dsr_erasure_physical_context_v1(p_plan_id);select*into p from public.dsr_erasure_plans_v1 where id=p_plan_id for update;if p_expected_content_hash is distinct from p.content_hash then raise exception'STALE_DSR_ERASURE_PLAN'using errcode='40001';end if;
 doc:=private.dsr_erasure_coverage_v1(p.id);sha:=encode(extensions.digest(convert_to(doc::text,'UTF8'),'sha256'),'hex');select*into e from public.dsr_erasure_executions_v1 where plan_id=p.id and sha256=sha;
 if e.id is null then insert into public.dsr_erasure_executions_v1(plan_id,request_id,content_hash,document_json,sha256,executed_by)values(p.id,p.request_id,p.content_hash,doc::text,sha,auth.uid())returning*into e;perform private.dsr_erasure_emit_v1(p.request_id,e.id,'privacy.erasure.report.prepared','DsrErasureReportPreparedV1',jsonb_build_object('plan_id',p.id,'execution_id',e.id,'sha256',sha,'complete',doc->'complete'));end if;
 return jsonb_build_object('outcome','DSR_ERASURE_REPORT_PREPARED','execution_id',e.id,'sha256',e.sha256,'complete',doc->'complete','pending_sources',doc->'pending_sources');
end$$;

create or replace function public.review_dsr_erasure_report_v1(p_execution_id uuid,p_expected_sha256 text,p_review_confirmed boolean,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare e public.dsr_erasure_executions_v1%rowtype;begin
 perform private.dsr_erasure_assert_current_actor_v1();select*into e from public.dsr_erasure_executions_v1 where id=p_execution_id for update;perform private.dsr_erasure_assert_current_actor_v1();
 if e.id is null or e.executed_by=auth.uid()then raise exception'DSR_ERASURE_INDEPENDENT_REPORT_REVIEW_REQUIRED'using errcode='42501';end if;perform private.dsr_erasure_physical_context_v1(e.plan_id);
 if p_expected_sha256 is distinct from e.sha256 then raise exception'STALE_DSR_ERASURE_REPORT'using errcode='40001';end if;
 if p_review_confirmed is distinct from true or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 then raise exception'DSR_ERASURE_REPORT_REVIEW_REQUIRED'using errcode='22023';end if;
 if exists(select 1 from public.dsr_erasure_report_reviews_v1 where execution_id=e.id and(reviewed_by<>auth.uid()or reason<>btrim(p_reason)))then raise exception'DSR_ERASURE_REPORT_ALREADY_REVIEWED'using errcode='55000';end if;
 if not exists(select 1 from public.dsr_erasure_report_reviews_v1 where execution_id=e.id)then insert into public.dsr_erasure_report_reviews_v1(execution_id,sha256,reviewed_by,reason)values(e.id,e.sha256,auth.uid(),btrim(p_reason));perform private.dsr_erasure_emit_v1(e.request_id,e.id,'privacy.erasure.report.reviewed','DsrErasureReportReviewedV1',jsonb_build_object('execution_id',e.id,'sha256',e.sha256,'complete',(e.document_json::jsonb)->'complete'));end if;
 return jsonb_build_object('outcome','DSR_ERASURE_REPORT_PUBLISHED','execution_id',e.id,'sha256',e.sha256,'complete',(e.document_json::jsonb)->'complete');
end$$;

create or replace function public.get_private_dsr_erasure_report_v1(p_execution_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare e public.dsr_erasure_executions_v1%rowtype;s public.dsr_erasure_scopes_v1%rowtype;subject_access boolean;begin
 perform private.dsr_erasure_assert_current_actor_v1(false);select*into e from public.dsr_erasure_executions_v1 where id=p_execution_id;select s0.*into s from public.dsr_erasure_scopes_v1 s0 join public.dsr_erasure_plans_v1 p on p.scope_version_id=s0.id where p.id=e.plan_id;
 subject_access:=auth.uid()is not null and auth.jwt()->>'aal'='aal2'and auth.uid()=s.subject_user_id and exists(select 1 from public.dsr_erasure_report_reviews_v1 where execution_id=e.id and sha256=e.sha256)and exists(select 1 from public.data_subject_requests where id=e.request_id and verified_at is not null);
 if e.id is null or not(private.dsr_response_staff_v1()or coalesce(subject_access,false))then raise exception'DSR_PRIVATE_ERASURE_REPORT_DENIED'using errcode='42501';end if;
 if subject_access then insert into public.dsr_erasure_proof_access_v1(execution_id,subject_user_id,sha256)values(e.id,auth.uid(),e.sha256)on conflict do nothing;end if;return jsonb_build_object('execution_id',e.id,'document_json',e.document_json,'sha256',e.sha256,'scope_version_id',s.id);
end$$;

create or replace function public.acknowledge_my_dsr_erasure_report_v1(p_execution_id uuid,p_expected_scope_version_id uuid,p_sha256 text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare e public.dsr_erasure_executions_v1%rowtype;s public.dsr_erasure_scopes_v1%rowtype;begin
 perform private.dsr_erasure_assert_current_actor_v1(false);select*into e from public.dsr_erasure_executions_v1 where id=p_execution_id;select s0.*into s from public.dsr_erasure_scopes_v1 s0 join public.dsr_erasure_plans_v1 p on p.scope_version_id=s0.id where p.id=e.plan_id;
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or s.subject_user_id is distinct from auth.uid()then raise exception'DSR_VERIFIED_ERASURE_SUBJECT_REQUIRED'using errcode='42501';end if;
 if e.id is null or p_expected_scope_version_id is distinct from s.id or p_sha256 is distinct from e.sha256 or s.id is distinct from(select id from public.dsr_erasure_scopes_v1 where request_id=e.request_id order by version desc limit 1)then raise exception'STALE_DSR_ERASURE_REPORT'using errcode='40001';end if;
 if not exists(select 1 from public.dsr_erasure_report_reviews_v1 where execution_id=e.id and sha256=e.sha256)or not exists(select 1 from public.dsr_erasure_proof_access_v1 where execution_id=e.id and subject_user_id=auth.uid()and sha256=e.sha256)then raise exception'DSR_ERASURE_REVIEWED_REPORT_ACCESS_REQUIRED'using errcode='55000';end if;
 if not exists(select 1 from public.dsr_erasure_proof_ack_v1 where execution_id=e.id)then insert into public.dsr_erasure_proof_ack_v1(execution_id,subject_user_id,sha256)values(e.id,auth.uid(),e.sha256);perform private.dsr_erasure_emit_v1(e.request_id,e.id,'privacy.erasure.report.acknowledged','DsrErasureReportAcknowledgedV1',jsonb_build_object('execution_id',e.id,'sha256',e.sha256,'automatically_fulfilled',false));end if;return jsonb_build_object('outcome','DSR_ERASURE_REPORT_ACKNOWLEDGED','execution_id',e.id,'sha256',e.sha256);
end$$;

create or replace function public.revoke_dsr_erasure_plan_v1(p_plan_id uuid,p_expected_content_hash text,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare p public.dsr_erasure_plans_v1%rowtype;begin
 perform private.dsr_erasure_assert_current_actor_v1();select*into p from public.dsr_erasure_plans_v1 where id=p_plan_id for update;perform private.dsr_erasure_assert_current_actor_v1();
 if p.id is null or p_expected_content_hash is distinct from p.content_hash then raise exception'STALE_DSR_ERASURE_PLAN'using errcode='40001';end if;if length(btrim(coalesce(p_reason,'')))not between 10 and 2000 then raise exception'DSR_ERASURE_REVOCATION_REASON_REQUIRED'using errcode='22023';end if;
 if exists(select 1 from public.dsr_erasure_revocations_v1 where plan_id=p.id and(reason<>btrim(p_reason)or revoked_by<>auth.uid()))then raise exception'DSR_ERASURE_ALREADY_REVOKED'using errcode='55000';end if;
 if not exists(select 1 from public.dsr_erasure_revocations_v1 where plan_id=p.id)then insert into public.dsr_erasure_revocations_v1(plan_id,content_hash,reason,revoked_by)values(p.id,p.content_hash,btrim(p_reason),auth.uid());perform private.dsr_erasure_emit_v1(p.request_id,p.id,'privacy.erasure.plan.revoked','DsrErasurePlanRevokedV1',jsonb_build_object('plan_id',p.id,'content_hash',p.content_hash,'previous_effects_reversed',false));end if;
 return jsonb_build_object('outcome','DSR_ERASURE_PLAN_REVOKED','plan_id',p.id,'previous_effects_reversed',false);
end$$;

create function private.dsr_erasure_native_domain_evidence_v1(p_plan_id uuid,p_source_key text)returns jsonb language sql stable security definer set search_path=pg_catalog as $$select jsonb_build_object('complete',false,'reason','TYPED_NATIVE_DOMAIN_EXECUTOR_REQUIRED')$$;
create or replace function private.dsr_erasure_coverage_v1(p_plan_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$declare p public.dsr_erasure_plans_v1%rowtype;x jsonb;receipt public.dsr_erasure_source_receipts_v1%rowtype;pending jsonb:='[]';sources jsonb:='[]';physical jsonb:=jsonb_build_object('complete',false,'reason','NATIVE_PHYSICAL_EXECUTOR_REQUIRED');external_current jsonb;domain_evidence jsonb;begin
 select*into p from public.dsr_erasure_plans_v1 where id=p_plan_id;if p.id is null then raise exception'DSR_ERASURE_PLAN_NOT_FOUND'using errcode='22023';end if;
 for x in select value from jsonb_array_elements(p.policy_json->'sources')loop
  if x#>>'{config,action}'='ACTION_REQUIRED'then pending:=pending||to_jsonb(x->>'source_key');
  elsif x#>>'{config,action}'in('ANONYMIZE_DISPLAY_NAME','ERASE_REMOVED_FAVORITE_NOTES')then
   select*into receipt from public.dsr_erasure_source_receipts_v1 where plan_id=p.id and source_key=x->>'source_key';
   if receipt.plan_id is null then pending:=pending||to_jsonb(x->>'source_key');
   elsif receipt.after_hash is distinct from private.dsr_erasure_target_hash_v1(p.request_id,(p.policy_json->>'subject_user_id')::uuid,x->>'source_key')then pending:=pending||to_jsonb((x->>'source_key')||':CHANGED_AFTER_EXECUTION');end if;
  elsif x#>>'{config,action}'not in('RETAIN_LEGAL','ERASE_PHYSICAL_STORAGE')then domain_evidence:=private.dsr_erasure_native_domain_evidence_v1(p.id,x->>'source_key');if coalesce((domain_evidence->>'complete')::boolean,false)is distinct from true or coalesce(domain_evidence->>'proof_hash','')!~'^[a-f0-9]{64}$'then pending:=pending||to_jsonb(x->>'source_key');end if;
  end if;
  -- Retention is disclosed as retention, not as deletion of the entire source.
  sources:=sources||jsonb_build_array(jsonb_build_object('source_key',x->>'source_key','disposition',x#>>'{config,action}','native_scope',x#>>'{source,native_scope}','legal_reference',x#>>'{config,legal_reference}','reason',x#>>'{config,reason}','retention_until',x#>>'{config,retention_until}','authorization_valid_until',x#>>'{config,authorization_valid_until}','retained_fields_until',x#>>'{config,retained_fields_until}','native_receipt',case when receipt.plan_id=p.id and receipt.source_key=x->>'source_key'then jsonb_build_object('proof_hash',receipt.proof_hash,'affected_rows',receipt.affected_rows::text,'retained_fields',receipt.retained_fields)else case when coalesce((domain_evidence->>'complete')::boolean,false)then jsonb_build_object('proof_hash',domain_evidence->>'proof_hash','affected_rows',domain_evidence->>'affected_rows','retained_fields',domain_evidence->'retained_fields')else null end end));
  receipt:=null;domain_evidence:=null;
 end loop;
 if to_regprocedure('private.dsr_erasure_physical_evidence_v1(uuid)')is not null then execute'select private.dsr_erasure_physical_evidence_v1($1)'into physical using p.id;end if;
 physical:=jsonb_build_object('complete',coalesce((physical->>'complete')::boolean,false),'manifest_hash',physical->>'manifest_hash','proof_hash',physical->>'proof_hash');
 if coalesce((physical->>'complete')::boolean,false)is distinct from true or coalesce(physical->>'manifest_hash','')!~'^[a-f0-9]{64}$'or coalesce(physical->>'proof_hash','')!~'^[a-f0-9]{64}$'then pending:=pending||'"@physical_storage"'::jsonb;end if;
 external_current:=private.dsr_all_external_processing_sources_v1(p.request_id);
 if coalesce((external_current->>'configured')::boolean,false)is distinct from true or external_current is distinct from p.policy_json->'external_processing'then pending:=pending||'"@processors_and_backups:REGISTRY_INCOMPLETE_OR_CHANGED"'::jsonb;end if;
 return jsonb_build_object('format','MATRICIA_ERASURE_COVERAGE_V2','plan_id',p.id,'request_id',p.request_id,'scope_version_id',p.scope_version_id,'policy_hash',p.content_hash,'complete',jsonb_array_length(pending)=0,'pending_sources',pending,'sources',sources,'physical_evidence',physical,'external_registry_hash',external_current->>'hash','preserved_history',jsonb_build_array('FINANCIAL_LEDGERS','CONTRACTS_AND_SIGNATURES','AUDIT_EVIDENCE','IDENTIFIER_ASSOCIATIONS_AND_OTHER_EXPLICITLY_RETAINED_FIELDS'),'meaning','SCOPED_DISPOSITIONS_WITH_EXPLICIT_LEGAL_RETENTION_NOT_UNQUALIFIED_TOTAL_DELETION');
end$$;
create or replace function public.get_dsr_erasure_console_v1(p_staff boolean default false,p_request_id uuid default null,p_draft_id uuid default null,p_plan_id uuid default null,p_page integer default 1,p_search text default '')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$declare reqs jsonb;draft public.dsr_erasure_drafts_v1%rowtype;plan public.dsr_erasure_plans_v1%rowtype;sources jsonb;drafts jsonb;plans jsonb;total bigint;begin
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or p_staff is null or(p_staff and not private.dsr_response_staff_v1())then raise exception'DSR_ERASURE_CONSOLE_DENIED'using errcode='42501';end if;
 if p_page is null or p_page not between 1 and 100000 or length(coalesce(p_search,''))>200 then raise exception'INVALID_DSR_ERASURE_PAGE'using errcode='22023';end if;
 if p_request_id is not null and not exists(select 1 from public.data_subject_requests d where d.id=p_request_id and d.request_type='ERASURE'and(p_staff or private.dsr_account_subject_v1(d.id)=auth.uid()or exists(select 1 from public.dsr_erasure_scopes_v1 s where s.request_id=d.id and s.subject_user_id=auth.uid())))then raise exception'DSR_ERASURE_CONSOLE_DENIED'using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'organization_id',d.organization_id,'status',d.status,'verified',d.verified_at is not null,'row_version',d.row_version,'scope',(select jsonb_build_object('id',id,'content_hash',content_hash,'version',version)from public.dsr_erasure_scopes_v1 where request_id=d.id order by version desc limit 1),'reports',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'plan_id',e.plan_id,'sha256',e.sha256,'complete',e.document_json::jsonb->'complete','policy_v2',not exists(select 1 from jsonb_array_elements(p.policy_json->'sources')x where x#>>'{config,schema_version}'is distinct from'2'),'published',exists(select 1 from public.dsr_erasure_report_reviews_v1 where execution_id=e.id),'acknowledged',exists(select 1 from public.dsr_erasure_proof_ack_v1 where execution_id=e.id),'scope_version_id',p.scope_version_id,'reference','privacy-erasure:'||e.id::text)order by e.executed_at desc,e.id)from(select*from public.dsr_erasure_executions_v1 where request_id=d.id order by executed_at desc,id limit 10 offset((p_page-1)*10))e join public.dsr_erasure_plans_v1 p on p.id=e.plan_id where p_staff or exists(select 1 from public.dsr_erasure_report_reviews_v1 where execution_id=e.id)),'[]'))order by d.created_at desc,d.id),'[]')into reqs from(select*from public.data_subject_requests d where d.request_type='ERASURE'and(p_request_id is null or d.id=p_request_id)and(p_staff or private.dsr_account_subject_v1(d.id)=auth.uid()or exists(select 1 from public.dsr_erasure_scopes_v1 where request_id=d.id and subject_user_id=auth.uid()))order by d.created_at desc,d.id limit 25 offset(case when p_request_id is null then(p_page-1)*25 else 0 end))d;
 if p_staff and p_request_id is not null then
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'created_by',created_by,'reason',reason,'catalog_hash',catalog_hash)order by created_at desc,id),'[]')into drafts from(select*from public.dsr_erasure_drafts_v1 where request_id=p_request_id order by created_at desc,id limit 25 offset((p_page-1)*25))x;
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'content_hash',p.content_hash,'created_by',p.created_by,'decision',r.decision,'reviewed_by',r.reviewed_by,'review_proof_hash',r.review_proof_hash)order by p.created_at desc,p.id),'[]')into plans from(select*from public.dsr_erasure_plans_v1 where request_id=p_request_id order by created_at desc,id limit 25 offset((p_page-1)*25))p left join public.dsr_erasure_reviews_v1 r on r.plan_id=p.id;
 end if;
 if p_draft_id is not null then
  if not p_staff then raise exception'DSR_ERASURE_CONSOLE_DENIED'using errcode='42501';end if;select*into draft from public.dsr_erasure_drafts_v1 where id=p_draft_id and request_id=p_request_id;if draft.id is null then raise exception'DSR_ERASURE_DRAFT_NOT_FOUND'using errcode='22023';end if;
  select count(*)into total from jsonb_array_elements(draft.catalog_json)e where p_search=''or e->>'key'ilike'%'||p_search||'%';
  select coalesce(jsonb_agg(jsonb_build_object('source',e.value,'config',r.config,'row_version',coalesce(r.row_version,0))order by e.value->>'key'),'[]')into sources from(select value from jsonb_array_elements(draft.catalog_json)where p_search=''or value->>'key'ilike'%'||p_search||'%'order by value->>'key'limit 25 offset((p_page-1)*25))e left join public.dsr_erasure_source_rules_v1 r on r.draft_id=draft.id and r.source_key=e.value->>'key';
 end if;
 if p_plan_id is not null then if not p_staff then raise exception'DSR_ERASURE_CONSOLE_DENIED'using errcode='42501';end if;select*into plan from public.dsr_erasure_plans_v1 where id=p_plan_id and request_id=p_request_id;if plan.id is null then raise exception'DSR_ERASURE_PLAN_NOT_FOUND'using errcode='22023';end if;end if;
 return jsonb_build_object('actor_id',auth.uid(),'can_manage',private.dsr_all_legal_staff_v1(),'requests',reqs,'page',p_page,'requests_has_next',exists(select 1 from public.data_subject_requests d where d.request_type='ERASURE'and(p_request_id is null or d.id=p_request_id)and(p_staff or private.dsr_account_subject_v1(d.id)=auth.uid()or exists(select 1 from public.dsr_erasure_scopes_v1 where request_id=d.id and subject_user_id=auth.uid()))offset(p_page*25)),'drafts',coalesce(drafts,'[]'),'plans',coalesce(plans,'[]'),'selected_draft',case when draft.id is null then null else jsonb_build_object('id',draft.id,'created_by',draft.created_by,'catalog_hash',draft.catalog_hash,'catalog_current',draft.catalog_hash=private.canonical_request_hash(private.dsr_erasure_catalog_v1()),'sealed',exists(select 1 from public.dsr_erasure_plans_v1 where draft_id=draft.id),'unclassified',(select count(*)from jsonb_array_elements(draft.catalog_json)e where not exists(select 1 from public.dsr_erasure_source_rules_v1 where draft_id=draft.id and source_key=e->>'key')),'sources',sources,'has_next',total>p_page::bigint*25)end,'selected_plan',case when plan.id is null then null else jsonb_build_object('id',plan.id,'content_hash',plan.content_hash,'created_by',plan.created_by,'catalog_current',plan.catalog_hash=private.canonical_request_hash(private.dsr_erasure_catalog_v1()),'policy',(plan.policy_json-'sources')||jsonb_build_object('source_count',jsonb_array_length(plan.policy_json->'sources'),'sources',(select coalesce(jsonb_agg(x.value order by x.value->>'source_key'),'[]')from(select value from jsonb_array_elements(plan.policy_json->'sources')where p_search=''or value->>'source_key'ilike'%'||p_search||'%'order by value->>'source_key'limit 25 offset((p_page-1)*25))x),'has_next',(select count(*)>p_page::bigint*25 from jsonb_array_elements(plan.policy_json->'sources')where p_search=''or value->>'source_key'ilike'%'||p_search||'%')),'revoked',exists(select 1 from public.dsr_erasure_revocations_v1 where plan_id=plan.id),'decision',(select decision from public.dsr_erasure_reviews_v1 where plan_id=plan.id),'reviewed_by',(select reviewed_by from public.dsr_erasure_reviews_v1 where plan_id=plan.id),'review_proof_hash',(select review_proof_hash from public.dsr_erasure_reviews_v1 where plan_id=plan.id))end);
end$$;
do $$declare definition text;needle text:='select*into d from public.data_subject_requests where id=p_request_id for update;';begin
 select pg_get_functiondef('public.transition_data_subject_request(uuid,integer,text,text,text,uuid)'::regprocedure)into definition;
 if strpos(definition,needle)=0 then raise exception'DSR_ERASURE_LOCK_ORDER_PATCH_TARGET_MISSING';end if;
 if strpos(definition,'dsr_erasure_assert_current_actor_v1(false)')=0 then definition:=replace(definition,needle,'if exists(select 1 from public.data_subject_requests where id=p_request_id and request_type=''ERASURE'')then perform private.dsr_erasure_assert_current_actor_v1(false);end if;'||needle);execute definition;end if;
end$$;
revoke all on function private.dsr_erasure_policy_actor_active_v1(uuid),private.dsr_erasure_policy_context_core_v1(uuid),private.dsr_erasure_native_domain_evidence_v1(uuid,text),private.dsr_erasure_lock_actors_v1(uuid[]),private.dsr_erasure_assert_current_actor_v1(boolean)from public,anon,authenticated,service_role;
